{
  "didatica": [
    {
      "campo": "resolucao.antes.texto",
      "depois": "Os pontos que ficam à mesma distância de dois pontos formam uma reta chamada mediatriz do segmento que os une. Ela passa pelo ponto médio e é perpendicular ao segmento. No quadrado STUV, os vilões T e V são vértices opostos, então a mediatriz de TV é a outra diagonal, a reta SU. O herói parte de S, que já está nessa reta. Falta achar a equação dela.",
      "motivo": "Frases mais curtas e sem repetir o termo antes de defini-lo."
    },
    {
      "campo": "resolucao.antes.simbolos",
      "depois": [
        ["equidistante", "que está à mesma distância de dois pontos"],
        ["mediatriz", "reta perpendicular a um segmento, passando pelo seu ponto médio; todos os seus pontos ficam à mesma distância das extremidades"],
        ["m", "coeficiente angular (inclinação) da reta: quanto y sobe quando x aumenta 1"],
        ["diagonal", "segmento que liga vértices opostos do quadrado"],
        ["vetor SV", "o deslocamento de S até V: quanto se anda em x e quanto em y"],
        ["perpendicular", "que forma ângulo reto (90°) com outra reta"]
      ],
      "motivo": "Incluir vetor e perpendicular, termos usados nos passos; explicar a inclinação."
    },
    {
      "campo": "resolucao.passos[2].porque",
      "depois": "Girar o deslocamento (a ; b) em 90° dá (−b ; a). O lado ST é o lado SV girado, com o mesmo tamanho. Confere com a figura: T está à esquerda de S, entre as alturas de S e V.",
      "motivo": "Mais simples e sem frase ambígua."
    },
    {
      "campo": "resolucao.passos[3].porque",
      "depois": "No quadrado, o lado TU é igual e paralelo ao lado SV, então U = T + (2 ; 4) = (4 ; 8). Na figura, U fica acima, entre T e V na horizontal.",
      "motivo": "Mais direto."
    },
    {
      "campo": "resolucao.passos[4].porque",
      "depois": "Confira: a inclinação de TV é (6−4) ÷ (8−2) = 1/3. O produto 1/3 × (−3) = −1 mostra que SU é perpendicular a TV.",
      "motivo": "Mantida a ideia, linguagem mais clara."
    },
    {
      "campo": "resolucao.quadro[8].linha",
      "depois": "y = −3x + 18 + 2",
      "motivo": "Falta passo intermediário: o aluno precisa ver y − 2 = −3x + 18 antes de mover o 2."
    },
    {
      "campo": "resolucao.quadro[8].nota",
      "depois": "distribua o −3 e passe o 2 para a direita (veja a linha anterior)",
      "motivo": "Nota curta e clara."
    }
  ],
